/** Normalised cards. Examples are ordered past, present, future for the timeline. */
export const SEED = RAW.map((r) => ({
  id: 's:' + r.w.toLowerCase().replace(/\s+/g, '-'),
  w: r.w,
  p: r.p,
  ipa: r.ipa,
  say: r.say,
  m: r.m,
  ex: [
    { t: 'Past', s: r.ex[1] },
    { t: 'Present', s: r.ex[0] },
    { t: 'Future', s: r.ex[2] },
  ],
  hi: r.hi,
  him: r.him,
  d: r.d,
  t: r.t,
  src: 'seed',
}));
